static int qiban_mkdir_p(FAR const char *path)
{
  char buffer[PATH_MAX];
  FAR char *cursor;
  size_t length;

  if (path == NULL || *path == '\0')
    {
      return -EINVAL;
    }

  length = strnlen(path, sizeof(buffer));
  if (length == 0 || length >= sizeof(buffer))
    {
      return -ENAMETOOLONG;
    }

  memcpy(buffer, path, length);
  buffer[length] = '\0';

  for (cursor = buffer + 1; *cursor != '\0'; cursor++)
    {
      if (*cursor != '/')
        {
          continue;
        }

      *cursor = '\0';
      if (mkdir(buffer, 0777) < 0 && errno != EEXIST)
        {
          return -errno;
        }

      *cursor = '/';
    }

  if (mkdir(buffer, 0777) < 0 && errno != EEXIST)
    {
      return -errno;
    }

  return OK;
}

static int qiban_ensure_parent_dir(FAR const char *path)
{
  char dir_path[PATH_MAX];
  FAR char *slash;
  size_t length;

  if (path == NULL || *path == '\0')
    {
      return -EINVAL;
    }

  length = strnlen(path, sizeof(dir_path));
  if (length == 0 || length >= sizeof(dir_path))
    {
      return -ENAMETOOLONG;
    }

  memcpy(dir_path, path, length);
  dir_path[length] = '\0';
  slash = strrchr(dir_path, '/');
  if (slash == NULL)
    {
      return -EINVAL;
    }

  if (slash == dir_path)
    {
      dir_path[1] = '\0';
    }
  else
    {
      *slash = '\0';
    }

  return qiban_mkdir_p(dir_path);
}

