static int qiban_parse_int(FAR const char *text, FAR int *out_value)
{
  FAR char *endptr;
  long value;

  if (text == NULL || *text == '\0')
    {
      return -EINVAL;
    }

  errno = 0;
  value = strtol(text, &endptr, 10);
  if (text == endptr || errno != 0)
    {
      return -EINVAL;
    }

  while (*endptr == ' ' || *endptr == '\t' || *endptr == '\n' ||
         *endptr == '\r')
    {
      endptr++;
    }

  if (*endptr != '\0')
    {
      return -EINVAL;
    }

  if (value < INT_MIN || value > INT_MAX)
    {
      return -ERANGE;
    }

  *out_value = (int)value;
  return OK;
}

