  FAR const char *cursor;
  FAR const char *start;
  FAR const char *end;
  size_t length;

  snprintf(pattern, sizeof(pattern), "\"%s\"", key);
  cursor = strstr(json, pattern);
  if (cursor == NULL)
    {
      return false;
