  for (cursor = (FAR const unsigned char *)text;
       cursor != NULL && *cursor != '\0';
       cursor++)
    {
      if (*cursor == '"' || *cursor == '\\')
        {
          fputc('\\', fp);
          fputc(*cursor, fp);
        }
      else if (*cursor == '\n')
        {
          fputs("\\n", fp);
