static int music_json_extract_string(FAR const char *json,
                                     FAR const char *key,
                                     FAR char *out, size_t outlen)
{
  char pattern[64];
  FAR char *p;
  FAR char *end;

  snprintf(pattern, sizeof(pattern), "\"%s\"", key);
  p = strstr(json, pattern);
  if (p == NULL)
