static void qiban_ui_map_zoom_event_cb(lv_event_t *event)
{
  FAR const char *direction;

  if (lv_event_get_code(event) != LV_EVENT_CLICKED)
    {
      return;
    }

  if (g_qiban_ui == NULL || g_qiban_ui->map_widget == NULL)
    {
      return;
    }

  direction = (FAR const char *)lv_event_get_user_data(event);
  if (direction == NULL)
    {
      return;
    }

  if (strcmp(direction, "in") == 0)
    {
      lv_offline_map_zoom_in(g_qiban_ui->map_widget);
      qiban_ui_set_map_pending(g_qiban_ui, "地图已放大");
    }
  else
    {
      lv_offline_map_zoom_out(g_qiban_ui->map_widget);
      qiban_ui_set_map_pending(g_qiban_ui, "地图已缩小");
    }
}

