  if (ui == NULL)
    {
      return;
    }

  qiban_ui_build_map_status(ui, map_status, sizeof(map_status));

  if (ui->map_widget != NULL)
    {
      qiban_ui_sync_offline_map_view(ui);
      qiban_ui_refresh_map_overlay(ui);
      lv_obj_clear_flag(ui->map_page_status_label, LV_OBJ_FLAG_HIDDEN);
      lv_label_set_text(ui->map_page_status_label, map_status);

      if (ui->map_page_placeholder != NULL)
        {
          if (!ui->map_state.ready && !ui->location_state.valid &&
              !ui->map_local_route_active &&
              !ui->nav_state.active)
            {
              lv_obj_clear_flag(ui->map_page_placeholder, LV_OBJ_FLAG_HIDDEN);
              lv_label_set_text(ui->map_page_placeholder,
                                "Waiting for map or GPS\nMap root: /data/qiban_offline_map/map/");
            }
          else
            {
              lv_obj_add_flag(ui->map_page_placeholder, LV_OBJ_FLAG_HIDDEN);
            }
        }
    }
  else
    {
      if (ui->map_page_placeholder != NULL)
        {
          lv_obj_clear_flag(ui->map_page_placeholder, LV_OBJ_FLAG_HIDDEN);
          lv_label_set_text(ui->map_page_placeholder,
                            "Offline map init failed");
        }
    }
}

