  double parsed_latitude;

  cursor = strstr(json, "\"location\"");
  if (cursor == NULL)
    {
      return -ENOENT;
    }

  start = strchr(cursor, ':');
  if (start == NULL)
    {
      return -EINVAL;
    }

  start = strchr(start, '"');
  if (start == NULL)
    {
      return -EINVAL;
    }

  start++;
  errno = 0;
  parsed_longitude = strtod(start, &endptr);
  if (start == endptr || errno != 0 || *endptr != ',')
    {
